create table property ( id varchar(36) primary key, title varchar(255) not null, address varchar(500) not null, city varchar(150) not null, country varchar(150) not null, created_at timestamp not null, contact_name varchar(255) not null default '', contact_number varchar(64) not null default '', time_zone varchar(120) not null default '', night_audit_time varchar(10) not null default '', check_in_time varchar(10) not null default '', check_out_time varchar(10) not null default '', status varchar(32) not null default 'ACTIVE', created_by varchar(120) not null default 'system', property_code varchar(120) not null default '', property_type varchar(80) not null default '', total_no_of_rooms integer not null default 0, total_no_of_floors integer not null default 0, state varchar(150) not null default '', zip_code varchar(40) not null default '', website varchar(255) not null default '' );
create table property_draft ( id bigint generated by default as identity primary key, wizard_data text not null, schema_version integer not null, status varchar(32) not null, published_property_id varchar(36), version bigint, created_at timestamp not null, updated_at timestamp not null, lifecycle_state varchar(32) not null default 'DRAFT', current_step varchar(64) not null default 'PROPERTY_DETAILS', completed_steps varchar(500) not null default '', created_by varchar(120) not null default 'system', updated_by varchar(120) not null default 'system', published_by varchar(120) );
create table tax ( id bigint generated by default as identity primary key, property_id varchar(36) not null unique, gst_number varchar(100) not null, tax_percentage double precision not null, constraint fk_tax_property foreign key (property_id) references property(id) );
