create table room_outlet_type ( id bigint generated by default as identity primary key, property_id varchar(36) not null, room_name varchar(150) not null, room_code varchar(80), quantity integer not null, available_for_sell boolean not null, maximum_guest_occupancy integer not null, description varchar(1000), amenities_csv varchar(2000), images_csv varchar(4000), constraint fk_room_outlet_type_property foreign key (property_id) references property(id) );
create table floor_property_area ( id bigint generated by default as identity primary key, property_id varchar(36) not null, floor_name varchar(120) not null, area_name varchar(150) not null, quantity integer not null, constraint fk_floor_property_area_property foreign key (property_id) references property(id) );
create table chart_of_account ( id bigint generated by default as identity primary key, property_id varchar(36) not null, account_code varchar(80) not null, account_name varchar(150) not null, account_type varchar(80) not null, ledger_type varchar(80) not null, active boolean not null, constraint fk_chart_of_account_property foreign key (property_id) references property(id) );
