package com.pms.property.publish.mapper;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.pms.property.common.exception.BadRequestException;
import com.pms.property.domain.content.entity.GuestServiceAmenityEntity;
import com.pms.property.domain.content.entity.NearbyLocationAccessibilityEntity;
import com.pms.property.domain.content.entity.PropertyOverviewEntity;
import com.pms.property.domain.finance.entity.ChartOfAccountEntity;
import com.pms.property.domain.finance.entity.RevenueMappingEntity;
import com.pms.property.domain.payment.entity.PaymentMethodEntity;
import com.pms.property.domain.property.entity.PropertyEntity;
import com.pms.property.domain.room.entity.FloorConfigurationEntity;
import com.pms.property.domain.room.entity.FloorPropertyAreaEntity;
import com.pms.property.domain.room.entity.InventoryRoomEntity;
import com.pms.property.domain.room.entity.PropertyAreaEntity;
import com.pms.property.domain.room.entity.RoomOutletTypeEntity;
import com.pms.property.domain.tax.entity.TaxRuleEntity;
import java.io.IOException;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import org.springframework.stereotype.Component;

@Component
public class PublishMapper {

    private final ObjectMapper objectMapper;

    public PublishMapper(ObjectMapper objectMapper) {
        this.objectMapper = objectMapper;
    }

    public NormalizedPublishData toNormalized(String wizardJson) {
        try {
            JsonNode root = objectMapper.readTree(wizardJson);
            JsonNode propertyNode = root.path("propertyDetails");
            JsonNode contentNode = root.path("content");
            JsonNode roomsAndOutletsNode = firstObjectNode(root, "roomsAndOutlets", "roomAndOutlets", "roomsOutlets");

            PropertyEntity property = new PropertyEntity();
            property.setTitle(firstText(propertyNode, "name", "propertyName"));
            property.setPropertyCode(firstText(propertyNode, "propertyCode"));
            property.setPropertyType(firstText(propertyNode, "propertyType"));
            property.setTotalNoOfRooms(firstInt(propertyNode, "totalNoOfRooms", "totalRooms"));
            property.setTotalNoOfFloors(firstInt(propertyNode, "totalNoOfFloors", "totalFloors"));
            property.setAddress(resolveAddress(propertyNode));
            property.setCity(firstText(propertyNode, "city"));
            property.setState(firstText(propertyNode, "state"));
            property.setCountry(firstText(propertyNode, "country"));
            property.setZipCode(firstText(propertyNode, "zipCode", "postalCode", "zipPostalCode"));
            property.setWebsite(firstText(propertyNode, "website"));
            property.setContactName(firstText(propertyNode, "contactName", "primaryContactName"));
            property.setContactNumber(firstText(propertyNode, "contactNumber", "phoneNumber", "phone"));
            property.setTimeZone(firstText(propertyNode, "timeZone"));
            property.setNightAuditTime(firstText(propertyNode, "nightAuditTime"));
            property.setCheckInTime(firstText(propertyNode, "checkInTime"));
            property.setCheckOutTime(firstText(propertyNode, "checkOutTime"));
            property.setStatus("ACTIVE");
            property.setCreatedAt(Instant.now());

            PropertyOverviewEntity propertyOverview = mapPropertyOverview(contentNode);
            List<GuestServiceAmenityEntity> guestServiceAmenities = mapGuestServiceAmenities(contentNode);
            List<NearbyLocationAccessibilityEntity> nearbyLocationAccessibility = mapNearbyLocationAccessibility(contentNode);
            List<PropertyAreaEntity> propertyAreas = mapPropertyAreas(roomsAndOutletsNode);
            List<RoomOutletTypeEntity> roomOutletTypes = mapRoomOutletTypes(roomsAndOutletsNode);

            List<FloorConfigurationEntity> floors = new ArrayList<>();
            List<FloorPropertyAreaEntity> floorPropertyAreas = new ArrayList<>();
            List<InventoryRoomEntity> inventoryRooms = new ArrayList<>();
            JsonNode floorConfigurationNode = firstObjectNode(root, "floorConfiguration", "roomConfiguration");
            for (JsonNode floorNode : floorConfigurationNode.path("floors")) {
                String floorName = firstText(floorNode, "floorName", "name", "label");
                JsonNode floorRoomTypes = floorNode.path("roomTypes");

                if (floorRoomTypes.isArray() && !floorRoomTypes.isEmpty()) {
                    for (JsonNode floorRoomTypeNode : floorRoomTypes) {
                        JsonNode manualRoomNumbers = floorRoomTypeNode.path("roomNumbers");
                        int configuredRoomCount = firstInt(floorRoomTypeNode, "roomCount", "quantity", "qty", "count");
                        int manualRoomCount = countRoomNumbers(manualRoomNumbers);

                        FloorConfigurationEntity floor = new FloorConfigurationEntity();
                        floor.setFloorName(floorName);
                        floor.setRoomTypeName(firstText(floorRoomTypeNode, "roomTypeCode", "code", "roomTypeName", "name", "roomName"));
                        floor.setRoomCount(configuredRoomCount > 0 ? configuredRoomCount : manualRoomCount);
                        floor.setStartNumber(resolveStartNumber(floorRoomTypeNode, manualRoomNumbers));
                        floors.add(floor);

                        appendInventoryRooms(inventoryRooms, floorName, floor.getRoomTypeName(), manualRoomNumbers);
                    }
                } else {
                    JsonNode manualRoomNumbers = floorNode.path("roomNumbers");
                    int configuredRoomCount = firstInt(floorNode, "roomCount", "quantity", "qty", "count");
                    int manualRoomCount = countRoomNumbers(manualRoomNumbers);

                    FloorConfigurationEntity floor = new FloorConfigurationEntity();
                    floor.setFloorName(floorName);
                    floor.setRoomTypeName(firstText(floorNode, "roomTypeCode", "code", "roomTypeName", "name", "roomName"));
                    floor.setRoomCount(configuredRoomCount > 0 ? configuredRoomCount : manualRoomCount);
                    floor.setStartNumber(resolveStartNumber(floorNode, manualRoomNumbers));
                    floors.add(floor);

                    appendInventoryRooms(inventoryRooms, floorName, floor.getRoomTypeName(), manualRoomNumbers);
                }

                for (JsonNode propertyAreaNode : floorNode.path("propertyAreas")) {
                    FloorPropertyAreaEntity floorPropertyArea = new FloorPropertyAreaEntity();
                    floorPropertyArea.setFloorName(floorName);
                    floorPropertyArea.setAreaName(firstText(propertyAreaNode, "propertyAreaCode", "areaName", "name", "code"));
                    floorPropertyArea.setQuantity(firstInt(propertyAreaNode, "quantity", "qty", "count"));
                    floorPropertyAreas.add(floorPropertyArea);
                }
            }

            List<ChartOfAccountEntity> chartOfAccounts = new ArrayList<>();
            for (JsonNode accountNode : root.path("finance").path("chartOfAccounts")) {
                ChartOfAccountEntity chartOfAccount = new ChartOfAccountEntity();
                chartOfAccount.setAccountCode(accountNode.path("accountCode").asText());
                chartOfAccount.setAccountName(accountNode.path("accountName").asText());
                chartOfAccount.setAccountType(accountNode.path("accountType").asText());
                chartOfAccount.setLedgerType(accountNode.path("ledgerType").asText());
                chartOfAccount.setActive(accountNode.path("active").asBoolean());
                chartOfAccounts.add(chartOfAccount);
            }

            List<RevenueMappingEntity> revenueMappings = new ArrayList<>();
            for (JsonNode mappingNode : root.path("finance").path("revenueMappings")) {
                RevenueMappingEntity mapping = new RevenueMappingEntity();
                mapping.setChargeType(mappingNode.path("chargeType").asText());
                mapping.setMapGlAccount(mappingNode.path("mapGlAccount").asText());
                mapping.setStatus(mappingNode.path("status").asText());
                mapping.setDescription(mappingNode.path("description").asText());
                revenueMappings.add(mapping);
            }

            List<PaymentMethodEntity> paymentMethods = new ArrayList<>();
            for (JsonNode methodNode : root.path("payments").path("methods")) {
                PaymentMethodEntity paymentMethod = new PaymentMethodEntity();
                paymentMethod.setPaymentMethod(methodNode.path("paymentMethod").asText());
                paymentMethod.setAccountMapping(methodNode.path("accountMapping").asText());
                paymentMethod.setAllowRefund(methodNode.path("allowRefund").asBoolean());
                paymentMethod.setActive(methodNode.path("active").asBoolean());
                paymentMethods.add(paymentMethod);
            }

            List<TaxRuleEntity> taxRules = new ArrayList<>();
            for (JsonNode taxRuleNode : root.path("taxes").path("rules")) {
                TaxRuleEntity rule = new TaxRuleEntity();
                rule.setTaxName(taxRuleNode.path("taxName").asText());
                rule.setType(taxRuleNode.path("type").asText());
                rule.setRate(taxRuleNode.path("rate").asDouble());
                rule.setApplicableOn(taxRuleNode.path("applicableOn").asText());
                rule.setInclExcl(taxRuleNode.path("inclExcl").asText());
                rule.setEffectiveDate(taxRuleNode.path("effectiveDate").asText());
                rule.setActive(taxRuleNode.path("active").asBoolean());
                rule.setStatus(taxRuleNode.path("status").asText());
                rule.setPriority(taxRuleNode.path("priority").asInt());
                taxRules.add(rule);
            }

            return new NormalizedPublishData(
                root,
                property,
                propertyOverview,
                guestServiceAmenities,
                nearbyLocationAccessibility,
                propertyAreas,
                roomOutletTypes,
                floors,
                floorPropertyAreas,
                inventoryRooms,
                chartOfAccounts,
                revenueMappings,
                paymentMethods,
                taxRules
            );
        } catch (IOException ex) {
            throw new BadRequestException("Draft JSON is not valid");
        }
    }

    private String firstText(JsonNode node, String... fields) {
        for (String field : fields) {
            JsonNode value = node.path(field);
            if (!value.isMissingNode() && !value.isNull()) {
                String text = value.asText().trim();
                if (!text.isBlank()) {
                    return text;
                }
            }
        }
        return "";
    }

    private String resolveAddress(JsonNode propertyNode) {
        String legacyAddress = firstText(propertyNode, "address");
        if (!legacyAddress.isBlank()) {
            return legacyAddress;
        }

        String addressLine1 = firstText(propertyNode, "addressLine1");
        String addressLine2 = firstText(propertyNode, "addressLine2");
        if (addressLine2.isBlank()) {
            return addressLine1;
        }
        return addressLine1 + ", " + addressLine2;
    }

    private PropertyOverviewEntity mapPropertyOverview(JsonNode contentNode) {
        JsonNode propertyOverviewNode = contentNode.path("propertyOverview");
        if (!propertyOverviewNode.isObject()) {
            return null;
        }

        String propertyDescription = firstText(propertyOverviewNode, "propertyDescription", "description");
        String propertyHeroImage = firstText(propertyOverviewNode, "propertyHeroImage", "propertyImage", "image", "imageUrl");
        if (propertyHeroImage.isBlank()) {
            propertyHeroImage = firstText(propertyOverviewNode.path("propertyHeroImage"), "url", "key", "id");
        }

        if (propertyDescription.isBlank() && propertyHeroImage.isBlank()) {
            return null;
        }

        PropertyOverviewEntity overview = new PropertyOverviewEntity();
        overview.setPropertyDescription(propertyDescription);
        overview.setPropertyHeroImage(propertyHeroImage);
        return overview;
    }

    private List<GuestServiceAmenityEntity> mapGuestServiceAmenities(JsonNode contentNode) {
        List<GuestServiceAmenityEntity> result = new ArrayList<>();
        JsonNode guestServicesAndAmenities = contentNode.path("guestServicesAndAmenities");

        appendGuestServiceAmenitySection(result, guestServicesAndAmenities.path("standardAmenities"), "STANDARD_AMENITIES");
        appendGuestServiceAmenitySection(result, guestServicesAndAmenities.path("paidServices"), "PAID_SERVICES");
        appendGuestServiceAmenitySection(result, guestServicesAndAmenities.path("onDemandServices"), "ON_DEMAND_SERVICES");

        return result;
    }

    private void appendGuestServiceAmenitySection(
        List<GuestServiceAmenityEntity> target,
        JsonNode items,
        String section
    ) {
        if (!items.isArray()) {
            return;
        }

        for (JsonNode itemNode : items) {
            String code = firstText(itemNode, "code", "name", "label");
            if (code.isBlank()) {
                continue;
            }

            GuestServiceAmenityEntity entity = new GuestServiceAmenityEntity();
            entity.setSection(section);
            entity.setCode(code);
            entity.setEnabled(itemNode.path("enabled").asBoolean(true));
            target.add(entity);
        }
    }

    private List<NearbyLocationAccessibilityEntity> mapNearbyLocationAccessibility(JsonNode contentNode) {
        List<NearbyLocationAccessibilityEntity> result = new ArrayList<>();
        JsonNode nearbyLocationAccessibility = contentNode.path("nearbyLocationAccessibility");

        appendNearbyLocationSection(
            result,
            nearbyLocationAccessibility.path("transportConnectivity"),
            "TRANSPORT_CONNECTIVITY"
        );
        appendNearbyLocationSection(
            result,
            nearbyLocationAccessibility.path("otherLandmarks"),
            "OTHER_LANDMARKS"
        );

        return result;
    }

    private void appendNearbyLocationSection(
        List<NearbyLocationAccessibilityEntity> target,
        JsonNode items,
        String section
    ) {
        if (!items.isArray()) {
            return;
        }

        for (JsonNode itemNode : items) {
            String locationType = firstText(itemNode, "type", "transportType", "landmarkType");
            String locationName = firstText(itemNode, "name", "transportName", "landmarkName");
            if (locationType.isBlank() || locationName.isBlank()) {
                continue;
            }

            NearbyLocationAccessibilityEntity entity = new NearbyLocationAccessibilityEntity();
            entity.setSection(section);
            entity.setLocationType(locationType);
            entity.setLocationName(locationName);
            entity.setDistanceValue(firstDouble(itemNode, "distance", "distanceValue"));
            entity.setDistanceUnit(firstText(itemNode, "distanceUnit"));
            entity.setTravelTimeValue(firstInt(itemNode, "travelTime", "travelTimeValue"));
            entity.setTravelTimeUnit(firstText(itemNode, "travelTimeUnit"));
            target.add(entity);
        }
    }

    private int firstInt(JsonNode node, String... fields) {
        for (String field : fields) {
            JsonNode value = node.path(field);
            if (!value.isMissingNode() && !value.isNull()) {
                if (value.isNumber()) {
                    return value.asInt();
                }
                String text = value.asText().trim();
                if (!text.isBlank()) {
                    try {
                        return Integer.parseInt(text);
                    } catch (NumberFormatException ignored) {
                        return 0;
                    }
                }
            }
        }
        return 0;
    }

    private double firstDouble(JsonNode node, String... fields) {
        for (String field : fields) {
            JsonNode value = node.path(field);
            if (!value.isMissingNode() && !value.isNull()) {
                if (value.isNumber()) {
                    return value.asDouble();
                }
                String text = value.asText().trim();
                if (!text.isBlank()) {
                    try {
                        return Double.parseDouble(text);
                    } catch (NumberFormatException ignored) {
                        return 0.0;
                    }
                }
            }
        }
        return 0.0;
    }

    private boolean firstBoolean(JsonNode node, boolean defaultValue, String... fields) {
        for (String field : fields) {
            JsonNode value = node.path(field);
            if (!value.isMissingNode() && !value.isNull()) {
                if (value.isBoolean()) {
                    return value.asBoolean();
                }
                String text = value.asText().trim();
                if (!text.isBlank()) {
                    return Boolean.parseBoolean(text);
                }
            }
        }
        return defaultValue;
    }

    private JsonNode firstObjectNode(JsonNode parent, String... fields) {
        for (String field : fields) {
            JsonNode node = parent.path(field);
            if (node.isObject()) {
                return node;
            }
        }
        return objectMapper.createObjectNode();
    }

    private List<PropertyAreaEntity> mapPropertyAreas(JsonNode roomsAndOutletsNode) {
        List<PropertyAreaEntity> result = new ArrayList<>();
        JsonNode propertyAreas = roomsAndOutletsNode.path("propertyAreas");
        if (!propertyAreas.isArray()) {
            return result;
        }

        for (JsonNode areaNode : propertyAreas) {
            String areaName = firstText(areaNode, "areaName", "name");
            if (areaName.isBlank()) {
                continue;
            }

            PropertyAreaEntity entity = new PropertyAreaEntity();
            entity.setAreaName(areaName);
            entity.setQuantity(firstInt(areaNode, "quantity", "qty", "count"));
            entity.setMaximumCapacity(firstInt(areaNode, "maximumCapacity", "maxCapacity", "occupancy"));
            entity.setDescription(firstText(areaNode, "description"));
            entity.setAmenitiesCsv(joinAsCsv(areaNode.path("amenities")));
            entity.setImagesCsv(joinAsCsv(areaNode.path("images")));
            result.add(entity);
        }
        return result;
    }

    private List<RoomOutletTypeEntity> mapRoomOutletTypes(JsonNode roomsAndOutletsNode) {
        List<RoomOutletTypeEntity> result = new ArrayList<>();
        JsonNode roomOutletTypes = roomsAndOutletsNode.path("roomTypes");
        if (!roomOutletTypes.isArray()) {
            return result;
        }

        for (JsonNode roomNode : roomOutletTypes) {
            String roomName = firstText(roomNode, "roomName", "name");
            if (roomName.isBlank()) {
                continue;
            }

            RoomOutletTypeEntity entity = new RoomOutletTypeEntity();
            entity.setRoomName(roomName);
            entity.setQuantity(firstInt(roomNode, "quantity", "qty", "count"));
            entity.setAvailableForSell(roomNode.path("availableForSell").asBoolean(true));
            entity.setMaximumGuestOccupancy(firstInt(roomNode, "maximumGuestOccupancy", "maxOccupancy", "occupancy"));
            entity.setDescription(firstText(roomNode, "description"));
            entity.setAmenitiesCsv(joinAsCsv(roomNode.path("amenities")));
            entity.setImagesCsv(joinAsCsv(roomNode.path("images")));
            result.add(entity);
        }
        return result;
    }

    private String joinAsCsv(JsonNode items) {
        if (!items.isArray()) {
            return "";
        }

        List<String> values = new ArrayList<>();
        for (JsonNode item : items) {
            if (item.isTextual()) {
                String text = item.asText().trim();
                if (!text.isBlank()) {
                    values.add(text);
                }
            } else if (item.isObject()) {
                String value = firstText(item, "value", "name", "code", "url", "id");
                if (!value.isBlank()) {
                    values.add(value);
                }
            }
        }
        return String.join(",", values);
    }

    private int countRoomNumbers(JsonNode roomNumbersNode) {
        if (!roomNumbersNode.isArray()) {
            return 0;
        }

        int count = 0;
        for (JsonNode roomNumberNode : roomNumbersNode) {
            String roomNumber = roomNumberNode.asText().trim();
            if (!roomNumber.isBlank()) {
                count++;
            }
        }
        return count;
    }

    private Integer resolveStartNumber(JsonNode floorNode, JsonNode roomNumbersNode) {
        int explicitStart = firstInt(floorNode, "startNumber");
        if (explicitStart > 0) {
            return explicitStart;
        }

        if (!roomNumbersNode.isArray() || roomNumbersNode.isEmpty()) {
            return 0;
        }

        Integer minParsed = null;
        for (JsonNode roomNumberNode : roomNumbersNode) {
            try {
                int parsed = Integer.parseInt(roomNumberNode.asText().trim());
                if (minParsed == null || parsed < minParsed) {
                    minParsed = parsed;
                }
            } catch (NumberFormatException ignored) {
                // Non-numeric room numbers are allowed; use 0 fallback.
            }
        }
        return minParsed != null ? minParsed : 0;
    }

    private void appendInventoryRooms(
        List<InventoryRoomEntity> target,
        String floorName,
        String roomTypeName,
        JsonNode manualRoomNumbers
    ) {
        if (!manualRoomNumbers.isArray() || manualRoomNumbers.isEmpty()) {
            return;
        }

        for (JsonNode roomNumberNode : manualRoomNumbers) {
            String roomNumber = roomNumberNode.asText().trim();
            if (roomNumber.isBlank()) {
                continue;
            }

            InventoryRoomEntity room = new InventoryRoomEntity();
            room.setFloorName(floorName);
            room.setRoomTypeName(roomTypeName);
            room.setRoomNumber(roomNumber);
            target.add(room);
        }
    }

    public record NormalizedPublishData(
        JsonNode root,
        PropertyEntity property,
        PropertyOverviewEntity propertyOverview,
        List<GuestServiceAmenityEntity> guestServiceAmenities,
        List<NearbyLocationAccessibilityEntity> nearbyLocationAccessibility,
        List<PropertyAreaEntity> propertyAreas,
        List<RoomOutletTypeEntity> roomOutletTypes,
        List<FloorConfigurationEntity> floors,
        List<FloorPropertyAreaEntity> floorPropertyAreas,
        List<InventoryRoomEntity> inventoryRooms,
        List<ChartOfAccountEntity> chartOfAccounts,
        List<RevenueMappingEntity> revenueMappings,
        List<PaymentMethodEntity> paymentMethods,
        List<TaxRuleEntity> taxRules
    ) {
    }
}

package com.pms.property.publish.mapper;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.pms.property.common.exception.BadRequestException;
import com.pms.property.domain.content.entity.GuestServiceAmenityEntity;
import com.pms.property.domain.content.entity.NearbyLocationAccessibilityEntity;
import com.pms.property.domain.content.entity.PropertyOverviewEntity;
import com.pms.property.domain.finance.entity.ChartOfAccountEntity;
import com.pms.property.domain.finance.entity.RevenueMappingEntity;
import com.pms.property.domain.payment.entity.PaymentMethodEntity;
import com.pms.property.domain.property.entity.PropertyEntity;
import com.pms.property.domain.room.entity.FloorConfigurationEntity;
import com.pms.property.domain.room.entity.FloorPropertyAreaEntity;
import com.pms.property.domain.room.entity.InventoryRoomEntity;
import com.pms.property.domain.room.entity.PropertyAreaEntity;
import com.pms.property.domain.room.entity.RoomOutletTypeEntity;
import com.pms.property.domain.tax.entity.TaxRuleEntity;
import java.io.IOException;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import org.springframework.stereotype.Component;

@Component
public class PublishMapper {

    private final ObjectMapper objectMapper;

    public PublishMapper(ObjectMapper objectMapper) {
        this.objectMapper = objectMapper;
    }

    public NormalizedPublishData toNormalized(String wizardJson) {
        try {
            JsonNode root = objectMapper.readTree(wizardJson);
            JsonNode propertyNode = root.path("propertyDetails");
            JsonNode contentNode = root.path("content");
            JsonNode roomsAndOutletsNode = firstObjectNode(root, "roomsAndOutlets", "roomAndOutlets", "roomsOutlets");

            PropertyEntity property = new PropertyEntity();
            property.setTitle(firstText(propertyNode, "name", "propertyName"));
            property.setPropertyCode(firstText(propertyNode, "propertyCode"));
            property.setPropertyType(firstText(propertyNode, "propertyType"));
            property.setTotalNoOfRooms(firstInt(propertyNode, "totalNoOfRooms", "totalRooms"));
            property.setTotalNoOfFloors(firstInt(propertyNode, "totalNoOfFloors", "totalFloors"));
            property.setAddress(resolveAddress(propertyNode));
            property.setCity(firstText(propertyNode, "city"));
            property.setState(firstText(propertyNode, "state"));
            property.setCountry(firstText(propertyNode, "country"));
            property.setZipCode(firstText(propertyNode, "zipCode", "postalCode", "zipPostalCode"));
            property.setWebsite(firstText(propertyNode, "website"));
            property.setContactName(firstText(propertyNode, "contactName", "primaryContactName"));
            property.setContactNumber(firstText(propertyNode, "contactNumber", "phoneNumber", "phone"));
            property.setTimeZone(firstText(propertyNode, "timeZone"));
            property.setNightAuditTime(firstText(propertyNode, "nightAuditTime"));
            property.setCheckInTime(firstText(propertyNode, "checkInTime"));
            property.setCheckOutTime(firstText(propertyNode, "checkOutTime"));
            property.setStatus("ACTIVE");
            property.setCreatedAt(Instant.now());

            PropertyOverviewEntity propertyOverview = mapPropertyOverview(contentNode);
            List<GuestServiceAmenityEntity> guestServiceAmenities = mapGuestServiceAmenities(contentNode);
            List<NearbyLocationAccessibilityEntity> nearbyLocationAccessibility = mapNearbyLocationAccessibility(contentNode);
            List<PropertyAreaEntity> propertyAreas = mapPropertyAreas(roomsAndOutletsNode);
            List<RoomOutletTypeEntity> roomOutletTypes = mapRoomOutletTypes(roomsAndOutletsNode);

            List<FloorConfigurationEntity> floors = new ArrayList<>();
            List<FloorPropertyAreaEntity> floorPropertyAreas = new ArrayList<>();
            List<InventoryRoomEntity> inventoryRooms = new ArrayList<>();
            JsonNode floorConfigurationNode = firstObjectNode(root, "floorConfiguration", "roomConfiguration");
            for (JsonNode floorNode : floorConfigurationNode.path("floors")) {
                String floorName = firstText(floorNode, "floorName", "name", "label");
                JsonNode floorRoomTypes = floorNode.path("roomTypes");

                if (floorRoomTypes.isArray() && !floorRoomTypes.isEmpty()) {
                    for (JsonNode floorRoomTypeNode : floorRoomTypes) {
                        JsonNode manualRoomNumbers = floorRoomTypeNode.path("roomNumbers");
                        int configuredRoomCount = firstInt(floorRoomTypeNode, "roomCount", "quantity", "qty", "count");
                        int manualRoomCount = countRoomNumbers(manualRoomNumbers);

                        FloorConfigurationEntity floor = new FloorConfigurationEntity();
                        floor.setFloorName(floorName);
                        floor.setRoomTypeName(firstText(floorRoomTypeNode, "roomTypeCode", "code", "roomTypeName", "name", "roomName"));
                        floor.setRoomCount(configuredRoomCount > 0 ? configuredRoomCount : manualRoomCount);
                        floor.setStartNumber(resolveStartNumber(floorRoomTypeNode, manualRoomNumbers));
                        floors.add(floor);

                        appendInventoryRooms(inventoryRooms, floorName, floor.getRoomTypeName(), manualRoomNumbers);
                    }
                } else {
                    JsonNode manualRoomNumbers = floorNode.path("roomNumbers");
                    int configuredRoomCount = firstInt(floorNode, "roomCount", "quantity", "qty", "count");
                    int manualRoomCount = countRoomNumbers(manualRoomNumbers);

                    FloorConfigurationEntity floor = new FloorConfigurationEntity();
                    floor.setFloorName(floorName);
                    floor.setRoomTypeName(firstText(floorNode, "roomTypeCode", "code", "roomTypeName", "name", "roomName"));
                    floor.setRoomCount(configuredRoomCount > 0 ? configuredRoomCount : manualRoomCount);
                    floor.setStartNumber(resolveStartNumber(floorNode, manualRoomNumbers));
                    floors.add(floor);

                    appendInventoryRooms(inventoryRooms, floorName, floor.getRoomTypeName(), manualRoomNumbers);
                }

                for (JsonNode propertyAreaNode : floorNode.path("propertyAreas")) {
                    FloorPropertyAreaEntity floorPropertyArea = new FloorPropertyAreaEntity();
                    floorPropertyArea.setFloorName(floorName);
                    floorPropertyArea.setAreaName(firstText(propertyAreaNode, "propertyAreaCode", "areaName", "name", "code"));
                    floorPropertyArea.setQuantity(firstInt(propertyAreaNode, "quantity", "qty", "count"));
                    floorPropertyAreas.add(floorPropertyArea);
                }
            }

            List<ChartOfAccountEntity> chartOfAccounts = new ArrayList<>();
            for (JsonNode accountNode : root.path("finance").path("chartOfAccounts")) {
                ChartOfAccountEntity chartOfAccount = new ChartOfAccountEntity();
                chartOfAccount.setAccountCode(accountNode.path("accountCode").asText());
                chartOfAccount.setAccountName(accountNode.path("accountName").asText());
                chartOfAccount.setAccountType(accountNode.path("accountType").asText());
                chartOfAccount.setLedgerType(accountNode.path("ledgerType").asText());
                chartOfAccount.setActive(accountNode.path("active").asBoolean());
                chartOfAccounts.add(chartOfAccount);
            }

            List<RevenueMappingEntity> revenueMappings = new ArrayList<>();
            for (JsonNode mappingNode : root.path("finance").path("revenueMappings")) {
                RevenueMappingEntity mapping = new RevenueMappingEntity();
                mapping.setChargeType(mappingNode.path("chargeType").asText());
                mapping.setMapGlAccount(mappingNode.path("mapGlAccount").asText());
                mapping.setStatus(mappingNode.path("status").asText());
                mapping.setDescription(mappingNode.path("description").asText());
                revenueMappings.add(mapping);
            }

            List<PaymentMethodEntity> paymentMethods = new ArrayList<>();
            for (JsonNode methodNode : root.path("payments").path("methods")) {
                PaymentMethodEntity paymentMethod = new PaymentMethodEntity();
                paymentMethod.setPaymentMethod(methodNode.path("paymentMethod").asText());
                paymentMethod.setAccountMapping(methodNode.path("accountMapping").asText());
                paymentMethod.setAllowRefund(methodNode.path("allowRefund").asBoolean());
                paymentMethod.setActive(methodNode.path("active").asBoolean());
                paymentMethods.add(paymentMethod);
            }

            List<TaxRuleEntity> taxRules = new ArrayList<>();
            for (JsonNode taxRuleNode : root.path("taxes").path("rules")) {
                TaxRuleEntity rule = new TaxRuleEntity();
                rule.setTaxName(taxRuleNode.path("taxName").asText());
                rule.setType(taxRuleNode.path("type").asText());
                rule.setRate(taxRuleNode.path("rate").asDouble());
                rule.setApplicableOn(taxRuleNode.path("applicableOn").asText());
                rule.setInclExcl(taxRuleNode.path("inclExcl").asText());
                rule.setEffectiveDate(taxRuleNode.path("effectiveDate").asText());
                rule.setActive(taxRuleNode.path("active").asBoolean());
                rule.setStatus(taxRuleNode.path("status").asText());
                rule.setPriority(taxRuleNode.path("priority").asInt());
                taxRules.add(rule);
            }

            return new NormalizedPublishData(
                root,
                property,
                propertyOverview,
                guestServiceAmenities,
                nearbyLocationAccessibility,
                propertyAreas,
                roomOutletTypes,
                floors,
                floorPropertyAreas,
                inventoryRooms,
                chartOfAccounts,
                revenueMappings,
                paymentMethods,
                taxRules
            );
        } catch (IOException ex) {
            throw new BadRequestException("Draft JSON is not valid");
        }
    }

    private String firstText(JsonNode node, String... fields) {
        for (String field : fields) {
            JsonNode value = node.path(field);
            if (!value.isMissingNode() && !value.isNull()) {
                String text = value.asText().trim();
                if (!text.isBlank()) {
                    return text;
                }
            }
        }
        return "";
    }

    private String resolveAddress(JsonNode propertyNode) {
        String legacyAddress = firstText(propertyNode, "address");
        if (!legacyAddress.isBlank()) {
            return legacyAddress;
        }

        String addressLine1 = firstText(propertyNode, "addressLine1");
        String addressLine2 = firstText(propertyNode, "addressLine2");
        if (addressLine2.isBlank()) {
            return addressLine1;
        }
        return addressLine1 + ", " + addressLine2;
    }

    private PropertyOverviewEntity mapPropertyOverview(JsonNode contentNode) {
        JsonNode propertyOverviewNode = contentNode.path("propertyOverview");
        if (!propertyOverviewNode.isObject()) {
            return null;
        }

        String propertyDescription = firstText(propertyOverviewNode, "propertyDescription", "description");
        String propertyHeroImage = firstText(propertyOverviewNode, "propertyHeroImage", "propertyImage", "image", "imageUrl");
        if (propertyHeroImage.isBlank()) {
            propertyHeroImage = firstText(propertyOverviewNode.path("propertyHeroImage"), "url", "key", "id");
        }

        if (propertyDescription.isBlank() && propertyHeroImage.isBlank()) {
            return null;
        }

        PropertyOverviewEntity overview = new PropertyOverviewEntity();
        overview.setPropertyDescription(propertyDescription);
        overview.setPropertyHeroImage(propertyHeroImage);
        return overview;
    }

    private List<GuestServiceAmenityEntity> mapGuestServiceAmenities(JsonNode contentNode) {
        List<GuestServiceAmenityEntity> result = new ArrayList<>();
        JsonNode guestServicesAndAmenities = contentNode.path("guestServicesAndAmenities");

        appendGuestServiceAmenitySection(result, guestServicesAndAmenities.path("standardAmenities"), "STANDARD_AMENITIES");
        appendGuestServiceAmenitySection(result, guestServicesAndAmenities.path("paidServices"), "PAID_SERVICES");
        appendGuestServiceAmenitySection(result, guestServicesAndAmenities.path("onDemandServices"), "ON_DEMAND_SERVICES");

        return result;
    }

    private void appendGuestServiceAmenitySection(
        List<GuestServiceAmenityEntity> target,
        JsonNode items,
        String section
    ) {
        if (!items.isArray()) {
            return;
        }

        for (JsonNode itemNode : items) {
            String code = firstText(itemNode, "code", "name", "label");
            if (code.isBlank()) {
                continue;
            }

            GuestServiceAmenityEntity entity = new GuestServiceAmenityEntity();
            entity.setSection(section);
            entity.setCode(code);
            entity.setEnabled(itemNode.path("enabled").asBoolean(true));
            target.add(entity);
        }
    }

    private List<NearbyLocationAccessibilityEntity> mapNearbyLocationAccessibility(JsonNode contentNode) {
        List<NearbyLocationAccessibilityEntity> result = new ArrayList<>();
        JsonNode nearbyLocationAccessibility = contentNode.path("nearbyLocationAccessibility");

        appendNearbyLocationSection(
            result,
            nearbyLocationAccessibility.path("transportConnectivity"),
            "TRANSPORT_CONNECTIVITY"
        );
        appendNearbyLocationSection(
            result,
            nearbyLocationAccessibility.path("otherLandmarks"),
            "OTHER_LANDMARKS"
        );

        return result;
    }

    private void appendNearbyLocationSection(
        List<NearbyLocationAccessibilityEntity> target,
        JsonNode items,
        String section
    ) {
        if (!items.isArray()) {
            return;
        }

        for (JsonNode itemNode : items) {
            String locationType = firstText(itemNode, "type", "transportType", "landmarkType");
            String locationName = firstText(itemNode, "name", "transportName", "landmarkName");
            if (locationType.isBlank() || locationName.isBlank()) {
                continue;
            }

            NearbyLocationAccessibilityEntity entity = new NearbyLocationAccessibilityEntity();
            entity.setSection(section);
            entity.setLocationType(locationType);
            entity.setLocationName(locationName);
            entity.setDistanceValue(firstDouble(itemNode, "distance", "distanceValue"));
            entity.setDistanceUnit(firstText(itemNode, "distanceUnit"));
            entity.setTravelTimeValue(firstInt(itemNode, "travelTime", "travelTimeValue"));
            entity.setTravelTimeUnit(firstText(itemNode, "travelTimeUnit"));
            target.add(entity);
        }
    }

    private int firstInt(JsonNode node, String... fields) {
        for (String field : fields) {
            JsonNode value = node.path(field);
            if (!value.isMissingNode() && !value.isNull()) {
                if (value.isNumber()) {
                    return value.asInt();
                }
                String text = value.asText().trim();
                if (!text.isBlank()) {
                    try {
                        return Integer.parseInt(text);
                    } catch (NumberFormatException ignored) {
                        return 0;
                    }
                }
            }
        }
        return 0;
    }

    private double firstDouble(JsonNode node, String... fields) {
        for (String field : fields) {
            JsonNode value = node.path(field);
            if (!value.isMissingNode() && !value.isNull()) {
                if (value.isNumber()) {
                    return value.asDouble();
                }
                String text = value.asText().trim();
                if (!text.isBlank()) {
                    try {
                        return Double.parseDouble(text);
                    } catch (NumberFormatException ignored) {
                        return 0.0;
                    }
                }
            }
        }
        return 0.0;
    }

    private boolean firstBoolean(JsonNode node, boolean defaultValue, String... fields) {
        for (String field : fields) {
            JsonNode value = node.path(field);
            if (!value.isMissingNode() && !value.isNull()) {
                if (value.isBoolean()) {
                    return value.asBoolean();
                }
                String text = value.asText().trim();
                if (!text.isBlank()) {
                    return Boolean.parseBoolean(text);
                }
            }
        }
        return defaultValue;
    }

    private JsonNode firstObjectNode(JsonNode parent, String... fields) {
        for (String field : fields) {
            JsonNode node = parent.path(field);
            if (node.isObject()) {
                return node;
            }
        }
        return objectMapper.createObjectNode();
    }

    private List<PropertyAreaEntity> mapPropertyAreas(JsonNode roomsAndOutletsNode) {
        List<PropertyAreaEntity> result = new ArrayList<>();
        JsonNode propertyAreas = roomsAndOutletsNode.path("propertyAreas");
        if (!propertyAreas.isArray()) {
            return result;
        }

        for (JsonNode areaNode : propertyAreas) {
            String areaName = firstText(areaNode, "areaName", "name");
            if (areaName.isBlank()) {
                continue;
            }

            PropertyAreaEntity entity = new PropertyAreaEntity();
            entity.setAreaName(areaName);
            entity.setQuantity(firstInt(areaNode, "quantity", "qty", "count"));
            entity.setMaximumCapacity(firstInt(areaNode, "maximumCapacity", "maxCapacity", "occupancy"));
            entity.setDescription(firstText(areaNode, "description"));
            entity.setAmenitiesCsv(joinAsCsv(areaNode.path("amenities")));
            entity.setImagesCsv(joinAsCsv(areaNode.path("images")));
            result.add(entity);
        }
        return result;
    }

    private List<RoomOutletTypeEntity> mapRoomOutletTypes(JsonNode roomsAndOutletsNode) {
        List<RoomOutletTypeEntity> result = new ArrayList<>();
        JsonNode roomOutletTypes = roomsAndOutletsNode.path("roomTypes");
        if (!roomOutletTypes.isArray()) {
            return result;
        }

        for (JsonNode roomNode : roomOutletTypes) {
            String roomName = firstText(roomNode, "roomName", "name");
            if (roomName.isBlank()) {
                continue;
            }

            RoomOutletTypeEntity entity = new RoomOutletTypeEntity();
            entity.setRoomName(roomName);
            entity.setRoomCode(firstText(roomNode, "roomCode", "roomTypeCode", "code"));
            entity.setQuantity(firstInt(roomNode, "quantity", "qty", "count"));
            entity.setAvailableForSell(roomNode.path("availableForSell").asBoolean(true));
            entity.setMaximumGuestOccupancy(firstInt(roomNode, "maximumGuestOccupancy", "maxOccupancy", "occupancy"));
            entity.setDescription(firstText(roomNode, "description"));
            entity.setAmenitiesCsv(joinAsCsv(roomNode.path("amenities")));
            entity.setImagesCsv(joinAsCsv(roomNode.path("images")));
            result.add(entity);
        }
        return result;
    }

    private String joinAsCsv(JsonNode items) {
        if (!items.isArray()) {
            return "";
        }

        List<String> values = new ArrayList<>();
        for (JsonNode item : items) {
            if (item.isTextual()) {
                String text = item.asText().trim();
                if (!text.isBlank()) {
                    values.add(text);
                }
            } else if (item.isObject()) {
                String value = firstText(item, "value", "name", "code", "url", "id");
                if (!value.isBlank()) {
                    values.add(value);
                }
            }
        }
        return String.join(",", values);
    }

    private int countRoomNumbers(JsonNode roomNumbersNode) {
        if (!roomNumbersNode.isArray()) {
            return 0;
        }

        int count = 0;
        for (JsonNode roomNumberNode : roomNumbersNode) {
            String roomNumber = roomNumberNode.asText().trim();
            if (!roomNumber.isBlank()) {
                count++;
            }
        }
        return count;
    }

    private Integer resolveStartNumber(JsonNode floorNode, JsonNode roomNumbersNode) {
        int explicitStart = firstInt(floorNode, "startNumber");
        if (explicitStart > 0) {
            return explicitStart;
        }

        if (!roomNumbersNode.isArray() || roomNumbersNode.isEmpty()) {
            return 0;
        }

        Integer minParsed = null;
        for (JsonNode roomNumberNode : roomNumbersNode) {
            try {
                int parsed = Integer.parseInt(roomNumberNode.asText().trim());
                if (minParsed == null || parsed < minParsed) {
                    minParsed = parsed;
                }
            } catch (NumberFormatException ignored) {
                // Non-numeric room numbers are allowed; use 0 fallback.
            }
        }
        return minParsed != null ? minParsed : 0;
    }

    private void appendInventoryRooms(
        List<InventoryRoomEntity> target,
        String floorName,
        String roomTypeName,
        JsonNode manualRoomNumbers
    ) {
        if (!manualRoomNumbers.isArray() || manualRoomNumbers.isEmpty()) {
            return;
        }

        for (JsonNode roomNumberNode : manualRoomNumbers) {
            String roomNumber = roomNumberNode.asText().trim();
            if (roomNumber.isBlank()) {
                continue;
            }

            InventoryRoomEntity room = new InventoryRoomEntity();
            room.setFloorName(floorName);
            room.setRoomTypeName(roomTypeName);
            room.setRoomNumber(roomNumber);
            target.add(room);
        }
    }

    public record NormalizedPublishData(
        JsonNode root,
        PropertyEntity property,
        PropertyOverviewEntity propertyOverview,
        List<GuestServiceAmenityEntity> guestServiceAmenities,
        List<NearbyLocationAccessibilityEntity> nearbyLocationAccessibility,
        List<PropertyAreaEntity> propertyAreas,
        List<RoomOutletTypeEntity> roomOutletTypes,
        List<FloorConfigurationEntity> floors,
        List<FloorPropertyAreaEntity> floorPropertyAreas,
        List<InventoryRoomEntity> inventoryRooms,
        List<ChartOfAccountEntity> chartOfAccounts,
        List<RevenueMappingEntity> revenueMappings,
        List<PaymentMethodEntity> paymentMethods,
        List<TaxRuleEntity> taxRules
    ) {
    }
}

package com.pms.property.publish.validator;

import com.fasterxml.jackson.databind.JsonNode;
import com.pms.property.common.exception.BadRequestException;
import com.pms.property.common.exception.ValidationException;
import java.time.LocalTime;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import org.springframework.stereotype.Component;

@Component
public class PublishValidator {

    public void validate(JsonNode root) {
        JsonNode propertyDetails = root.path("propertyDetails");
        JsonNode roomsAndOutlets = firstObjectNode(root, "roomsAndOutlets", "roomAndOutlets", "roomsOutlets");
        validatePropertyDetails(propertyDetails);
        AllocationLimits allocationLimits = validateRoomsAndOutlets(
            roomsAndOutlets,
            firstInt(propertyDetails, "totalNoOfRooms", "totalRooms")
        );
        JsonNode floorConfiguration = firstObjectNode(root, "floorConfiguration", "roomConfiguration");
        validateRoomConfiguration(floorConfiguration, allocationLimits);
        validateFinance(root.path("finance"));
        validatePayments(root.path("payments"));
        validateTaxes(root.path("taxes"));
    }

    private AllocationLimits validateRoomsAndOutlets(JsonNode roomsAndOutlets, int totalRoomsFromPropertyDetails) {
        Map<String, Integer> roomTypeLimits = new HashMap<>();
        Map<String, Integer> propertyAreaLimits = new HashMap<>();
        JsonNode propertyAreas = roomsAndOutlets.path("propertyAreas");
        if (propertyAreas.isArray()) {
            Set<String> propertyAreaNames = new HashSet<>();
            for (JsonNode propertyArea : propertyAreas) {
                String propertyAreaKey = resolvePropertyAreaKey(propertyArea, "roomsAndOutlets.propertyAreas[]");
                if (!propertyAreaNames.add(propertyAreaKey)) {
                    throw new BadRequestException("Property area name must be unique and non-empty");
                }
                int quantity = firstInt(propertyArea, "quantity", "qty", "count");
                if (quantity <= 0) {
                    throw new BadRequestException("Property area quantity must be greater than zero");
                }
                propertyAreaLimits.put(propertyAreaKey, quantity);

                int maximumCapacity = firstInt(propertyArea, "maximumCapacity", "maxCapacity", "occupancy");
                if (maximumCapacity <= 0) {
                    throw new BadRequestException("Property area maximumCapacity must be greater than zero");
                }
            }
        }

        JsonNode roomTypes = roomsAndOutlets.path("roomTypes");
        if (roomTypes.isArray()) {
            int totalRoomTypeQuantity = 0;
            for (JsonNode roomType : roomTypes) {
                requireAny(roomType, "roomTypeCode", "code", "roomName", "name");
                int quantity = firstInt(roomType, "quantity", "qty", "count");
                if (quantity <= 0) {
                    throw new BadRequestException("Room type quantity must be greater than zero");
                }
                totalRoomTypeQuantity += quantity;
                String roomTypeKey = resolveRoomTypeKey(roomType, "roomsAndOutlets.roomTypes[]");
                roomTypeLimits.put(roomTypeKey, quantity);

                int maximumGuestOccupancy = firstInt(roomType, "maximumGuestOccupancy", "maxOccupancy", "occupancy");
                if (maximumGuestOccupancy <= 0) {
                    throw new BadRequestException("Room type maximumGuestOccupancy must be greater than zero");
                }
            }

            if (totalRoomTypeQuantity > 0 && totalRoomTypeQuantity != totalRoomsFromPropertyDetails) {
                throw new BadRequestException("Sum of room type quantities must equal totalNoOfRooms");
            }
        }

        return new AllocationLimits(roomTypeLimits, propertyAreaLimits);
    }

    private void validatePropertyDetails(JsonNode propertyDetails) {
        requireAny(propertyDetails, "name", "propertyName");
        requireAny(propertyDetails, "propertyType", "type");
        require(propertyDetails, "propertyCode");
        requireAny(propertyDetails, "totalNoOfRooms", "totalRooms");
        requireAny(propertyDetails, "totalNoOfFloors", "totalFloors");
        requireAny(propertyDetails, "address", "addressLine1");
        require(propertyDetails, "city");
        require(propertyDetails, "state");
        require(propertyDetails, "country");
        requireAny(propertyDetails, "zipCode", "postalCode", "zipPostalCode");
        requireAny(propertyDetails, "contactName", "primaryContactName");
        requireAny(propertyDetails, "contactNumber", "phoneNumber", "phone");
        require(propertyDetails, "timeZone");
        require(propertyDetails, "nightAuditTime");
        require(propertyDetails, "checkInTime");
        require(propertyDetails, "checkOutTime");

        int totalRooms = firstInt(propertyDetails, "totalNoOfRooms", "totalRooms");
        if (totalRooms <= 0) {
            throw new BadRequestException("totalNoOfRooms must be greater than zero");
        }

        int totalFloors = firstInt(propertyDetails, "totalNoOfFloors", "totalFloors");
        if (totalFloors <= 0) {
            throw new BadRequestException("totalNoOfFloors must be greater than zero");
        }

        String address = firstText(propertyDetails, "address", "addressLine1");
        if (address.length() < 10) {
            throw new BadRequestException("Address must have at least 10 characters");
        }

        String website = firstText(propertyDetails, "website");
        if (!website.isBlank() && !website.contains(".")) {
            throw new BadRequestException("Invalid website value");
        }

        String checkIn = firstText(propertyDetails, "checkInTime");
        String checkOut = firstText(propertyDetails, "checkOutTime");
        parseTime(checkIn, "checkInTime");
        parseTime(checkOut, "checkOutTime");
        parseTime(firstText(propertyDetails, "nightAuditTime"), "nightAuditTime");
        if (checkIn.equals(checkOut)) {
            throw new BadRequestException("checkOutTime must differ from checkInTime");
        }
    }

    private void validateRoomConfiguration(JsonNode roomConfiguration, AllocationLimits limits) {
        JsonNode floors = roomConfiguration.path("floors");
        if (limits.roomTypeLimits().isEmpty()) {
            throw new BadRequestException("At least one room type is required");
        }
        if (!floors.isArray() || floors.isEmpty()) {
            throw new BadRequestException("At least one floor configuration is required");
        }

        // roomConfiguration.roomTypes is optional; authoritative configured room types come from roomsAndOutlets.roomTypes.
        Set<String> roomTypeNames = new HashSet<>(limits.roomTypeLimits().keySet());

        Set<String> roomNumbers = new HashSet<>();
        Map<String, Integer> assignedPerRoomType = new HashMap<>();
        Map<String, Integer> assignedPerPropertyArea = new HashMap<>();
        int floorIndex = 0;
        for (JsonNode floor : floors) {
            requireAny(floor, "floorName", "name", "label");

            JsonNode nestedRoomTypes = floor.path("roomTypes");
            if (nestedRoomTypes.isArray() && !nestedRoomTypes.isEmpty()) {

                int roomTypeIndex = 0;

                for (JsonNode floorRoomType : nestedRoomTypes) {
                    String pathPrefix =
                            "roomConfiguration.floors[" + floorIndex + "].roomTypes[" + roomTypeIndex + "]";

                    validateFloorRoomTypeAssignment(
                            floorRoomType,
                            pathPrefix,
                            roomTypeNames,
                            roomNumbers,
                            assignedPerRoomType,
                            limits.roomTypeLimits()
                    );

                    roomTypeIndex++;
                }

            }

            JsonNode propertyAreas = floor.path("propertyAreas");
            if (propertyAreas.isArray()) {
                int propertyAreaIndex = 0;
                for (JsonNode floorPropertyArea : propertyAreas) {
                    String propertyAreaName = resolvePropertyAreaKey(
                        floorPropertyArea,
                        "roomConfiguration.floors[" + floorIndex + "].propertyAreas[" + propertyAreaIndex + "]"
                    );
                    if (!limits.propertyAreaLimits().containsKey(propertyAreaName)) {
                        throw validationError(
                            "UNKNOWN_PROPERTY_AREA",
                            "roomConfiguration.floors[" + floorIndex + "].propertyAreas[" + propertyAreaIndex + "]",
                            "Floor mapped to unknown property area: " + propertyAreaName
                        );
                    }

                    int assignedAreaCount = firstInt(floorPropertyArea, "quantity", "qty", "count");
                    if (assignedAreaCount <= 0) {
                        throw validationError(
                            "MISSING_PROPERTY_AREA_ASSIGNMENT",
                            "roomConfiguration.floors[" + floorIndex + "].propertyAreas[" + propertyAreaIndex + "]",
                            "Each property area assignment must include positive quantity"
                        );
                    }

                    int totalAreaAssigned = assignedPerPropertyArea.getOrDefault(propertyAreaName, 0) + assignedAreaCount;
                    assignedPerPropertyArea.put(propertyAreaName, totalAreaAssigned);

                    int configuredAreaLimit = limits.propertyAreaLimits().get(propertyAreaName);
                    if (totalAreaAssigned > configuredAreaLimit) {
                        throw validationError(
                            "PROPERTY_AREA_QUANTITY_EXCEEDED",
                            "roomConfiguration.floors[" + floorIndex + "].propertyAreas[" + propertyAreaIndex + "]",
                            "Assigned property areas exceed configured quantity for area: " + propertyAreaName
                        );
                    }
                    propertyAreaIndex++;
                }
            }

            floorIndex++;
        }

        for (String configuredRoomType : roomTypeNames) {
            if (assignedPerRoomType.getOrDefault(configuredRoomType, 0) <= 0) {
                throw validationError(
                    "ROOM_TYPE_UNASSIGNED",
                    "roomConfiguration.roomTypes",
                    "At least one room must be assigned for room type: " + configuredRoomType
                );
            }
        }
    }

    private ValidationException validationError(String code, String fieldPath, String message) {
        return new ValidationException(code, fieldPath, message);
    }

    private void validateFloorRoomTypeAssignment(
        JsonNode floorRoomType,
        String fieldPath,
        Set<String> roomTypeNames,
        Set<String> roomNumbers,
        Map<String, Integer> assignedPerRoomType,
        Map<String, Integer> roomTypeLimits
    ) {
        String roomTypeName = resolveRoomTypeKey(floorRoomType, fieldPath);
        if (!roomTypeNames.contains(roomTypeName)) {
            throw validationError(
                "UNKNOWN_ROOM_TYPE",
                fieldPath,
                "Floor mapped to unknown room type: " + roomTypeName
            );
        }

        int assignedCount = resolveAssignedRoomCount(floorRoomType, fieldPath, roomNumbers);
        int totalAssigned = assignedPerRoomType.getOrDefault(roomTypeName, 0) + assignedCount;
        assignedPerRoomType.put(roomTypeName, totalAssigned);

        Integer configuredLimit = roomTypeLimits.get(roomTypeName);
        if (configuredLimit != null && totalAssigned > configuredLimit) {
            throw validationError(
                "ROOM_TYPE_QUANTITY_EXCEEDED",
                fieldPath,
                "Assigned rooms exceed configured quantity for room type: " + roomTypeName
            );
        }
    }

    private int resolveAssignedRoomCount(JsonNode floorRoomType, String fieldPath, Set<String> roomNumbers) {
        JsonNode explicitRooms = floorRoomType.path("roomNumbers");
        if (explicitRooms.isArray() && !explicitRooms.isEmpty()) {
            int assignedCount = 0;
            for (JsonNode roomNumberNode : explicitRooms) {
                String roomNumber = roomNumberNode.asText().trim();
                if (roomNumber.isBlank() || !roomNumbers.add(roomNumber)) {
                    throw validationError(
                        "DUPLICATE_OR_BLANK_ROOM_NUMBER",
                        fieldPath + ".roomNumbers",
                        "Duplicate or blank room number found"
                    );
                }
                assignedCount++;
            }
            return assignedCount;
        }

        int assignedCount = firstInt(floorRoomType, "roomCount", "quantity", "qty", "count");
        if (assignedCount <= 0) {
            throw validationError(
                "MISSING_ROOM_ASSIGNMENT",
                fieldPath,
                "Each floor allocation must include roomNumbers or positive roomCount"
            );
        }
        return assignedCount;
    }

    private String resolveRoomTypeKey(JsonNode node, String fieldPath) {
        String key = firstText(node, "roomTypeCode", "code", "roomTypeName", "name", "roomName");
        if (key.isBlank()) {
            throw validationError("MISSING_ROOM_TYPE_KEY", fieldPath, "Room type identifier is required");
        }
        return key;
    }

    private String resolvePropertyAreaKey(JsonNode node, String fieldPath) {
        String key = firstText(node, "propertyAreaCode", "areaName", "name", "code");
        if (key.isBlank()) {
            throw validationError("MISSING_PROPERTY_AREA_KEY", fieldPath, "Property area identifier is required");
        }
        return key;
    }

    private void validateFinance(JsonNode finance) {
        JsonNode chartOfAccounts = finance.path("chartOfAccounts");
        JsonNode revenueMappings = finance.path("revenueMappings");
        if (!chartOfAccounts.isArray() || chartOfAccounts.isEmpty()) {
            throw new BadRequestException("At least one chart of account entry is required");
        }
        if (!revenueMappings.isArray() || revenueMappings.isEmpty()) {
            throw new BadRequestException("At least one revenue mapping is required");
        }

        Set<String> accountCodes = new HashSet<>();
        for (JsonNode account : chartOfAccounts) {
            String accountCode = account.path("accountCode").asText().trim();
            if (accountCode.isBlank()) {
                throw new BadRequestException("accountCode is required in chartOfAccounts");
            }

            String accountName = account.path("accountName").asText().trim();
            if (accountName.isBlank()) {
                throw new BadRequestException("accountName is required in chartOfAccounts");
            }

            String accountType = account.path("accountType").asText().trim();
            if (accountType.isBlank()) {
                throw new BadRequestException("accountType is required in chartOfAccounts");
            }

            String ledgerType = account.path("ledgerType").asText().trim();
            if (ledgerType.isBlank()) {
                throw new BadRequestException("ledgerType is required in chartOfAccounts");
            }

            if (account.path("active").isMissingNode() || account.path("active").isNull()) {
                throw new BadRequestException("active is required in chartOfAccounts");
            }

            accountCodes.add(accountCode);
        }

        for (JsonNode mapping : revenueMappings) {
            String chargeType = mapping.path("chargeType").asText().trim();
            if (chargeType.isBlank()) {
                throw new BadRequestException("chargeType is required in revenueMappings");
            }

            String mapGlAccount = mapping.path("mapGlAccount").asText().trim();
            if (!mapGlAccount.isBlank() && !"UNASSIGNED".equalsIgnoreCase(mapGlAccount) && !accountCodes.contains(mapGlAccount)) {
                throw new BadRequestException("Revenue mapping refers to unknown accountCode: " + mapGlAccount);
            }

            String status = mapping.path("status").asText().trim();
            if (status.isBlank()) {
                throw new BadRequestException("status is required in revenueMappings");
            }
        }
    }

    private void validatePayments(JsonNode payments) {
        JsonNode methods = payments.path("methods");
        if (!methods.isArray() || methods.isEmpty()) {
            throw new BadRequestException("At least one payment method is required");
        }

        for (JsonNode method : methods) {
            require(method, "paymentMethod");
            require(method, "accountMapping");
            if (method.path("allowRefund").isMissingNode() || method.path("allowRefund").isNull()) {
                throw new BadRequestException("allowRefund is required in payments.methods");
            }
            if (method.path("active").isMissingNode() || method.path("active").isNull()) {
                throw new BadRequestException("active is required in payments.methods");
            }
        }
    }

    private void validateTaxes(JsonNode taxes) {
        JsonNode rules = taxes.path("rules");
        if (!rules.isArray() || rules.isEmpty()) {
            throw new BadRequestException("At least one tax rule is required");
        }
        for (JsonNode rule : rules) {
            require(rule, "taxName");
            require(rule, "type");
            require(rule, "applicableOn");
            require(rule, "inclExcl");
            require(rule, "effectiveDate");
            require(rule, "status");
            if (rule.path("active").isMissingNode() || rule.path("active").isNull()) {
                throw new BadRequestException("active is required in taxes.rules");
            }
            if (rule.path("rate").asDouble() <= 0) {
                throw new BadRequestException("Tax rate must be greater than zero");
            }
        }
    }

    private void require(JsonNode node, String field) {
        JsonNode value = node.path(field);
        if (value.isMissingNode() || value.isNull() || (value.isTextual() && value.asText().isBlank())) {
            throw new BadRequestException("Missing required field: " + field);
        }
    }

    private void requireAny(JsonNode node, String... fields) {
        for (String field : fields) {
            JsonNode value = node.path(field);
            if (!value.isMissingNode() && !value.isNull() && (!value.isTextual() || !value.asText().isBlank())) {
                return;
            }
        }
        throw new BadRequestException("Missing required field: one of " + String.join(", ", fields));
    }

    private String firstText(JsonNode node, String... fields) {
        for (String field : fields) {
            JsonNode value = node.path(field);
            if (!value.isMissingNode() && !value.isNull()) {
                String text = value.asText().trim();
                if (!text.isBlank()) {
                    return text;
                }
            }
        }
        return "";
    }

    private int firstInt(JsonNode node, String... fields) {
        for (String field : fields) {
            JsonNode value = node.path(field);
            if (!value.isMissingNode() && !value.isNull()) {
                if (value.isNumber()) {
                    return value.asInt();
                }
                String text = value.asText().trim();
                if (!text.isBlank()) {
                    try {
                        return Integer.parseInt(text);
                    } catch (NumberFormatException ignored) {
                        return -1;
                    }
                }
            }
        }
        return -1;
    }

    private JsonNode firstObjectNode(JsonNode parent, String... fields) {
        for (String field : fields) {
            JsonNode node = parent.path(field);
            if (node.isObject()) {
                return node;
            }
        }
        return parent.path("__missing__");
    }

    private void parseTime(String value, String fieldName) {
        try {
            LocalTime.parse(value);
            return;
        } catch (DateTimeParseException ex) {
            // Fallback for 12-hour values from UI widgets, e.g. 11:55 AM
            try {
                DateTimeFormatter twelveHour = DateTimeFormatter.ofPattern("h:mm a", Locale.ENGLISH);
                LocalTime.parse(value.toUpperCase(Locale.ENGLISH), twelveHour);
            } catch (DateTimeParseException innerEx) {
                throw new BadRequestException("Invalid time format for: " + fieldName);
            }
        }
    }

    private record AllocationLimits(Map<String, Integer> roomTypeLimits, Map<String, Integer> propertyAreaLimits) {
    }
}

package com.pms.property.publish.validator;

import com.fasterxml.jackson.databind.JsonNode;
import com.pms.property.common.exception.BadRequestException;
import com.pms.property.common.exception.ValidationException;
import java.time.LocalTime;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.regex.Pattern;
import org.springframework.stereotype.Component;

@Component
public class PublishValidator {

    private static final Pattern ROOM_CODE_PATTERN = Pattern.compile("^[A-Z_]{2,20}$");

    public void validate(JsonNode root) {
        JsonNode propertyDetails = root.path("propertyDetails");
        JsonNode roomsAndOutlets = firstObjectNode(root, "roomsAndOutlets", "roomAndOutlets", "roomsOutlets");
        validatePropertyDetails(propertyDetails);
        AllocationLimits allocationLimits = validateRoomsAndOutlets(
            roomsAndOutlets,
            firstInt(propertyDetails, "totalNoOfRooms", "totalRooms")
        );
        JsonNode floorConfiguration = firstObjectNode(root, "floorConfiguration", "roomConfiguration");
        validateRoomConfiguration(floorConfiguration, allocationLimits);
        validateFinance(root.path("finance"));
        validatePayments(root.path("payments"));
        validateTaxes(root.path("taxes"));
    }

    private AllocationLimits validateRoomsAndOutlets(JsonNode roomsAndOutlets, int totalRoomsFromPropertyDetails) {
        Map<String, Integer> roomTypeLimits = new HashMap<>();
        Map<String, Integer> propertyAreaLimits = new HashMap<>();
        JsonNode propertyAreas = roomsAndOutlets.path("propertyAreas");
        if (propertyAreas.isArray()) {
            Set<String> propertyAreaNames = new HashSet<>();
            for (JsonNode propertyArea : propertyAreas) {
                String propertyAreaKey = resolvePropertyAreaKey(propertyArea, "roomsAndOutlets.propertyAreas[]");
                if (!propertyAreaNames.add(propertyAreaKey)) {
                    throw new BadRequestException("Property area name must be unique and non-empty");
                }
                int quantity = firstInt(propertyArea, "quantity", "qty", "count");
                if (quantity <= 0) {
                    throw new BadRequestException("Property area quantity must be greater than zero");
                }
                propertyAreaLimits.put(propertyAreaKey, quantity);

                int maximumCapacity = firstInt(propertyArea, "maximumCapacity", "maxCapacity", "occupancy");
                if (maximumCapacity <= 0) {
                    throw new BadRequestException("Property area maximumCapacity must be greater than zero");
                }
            }
        }

        JsonNode roomTypes = roomsAndOutlets.path("roomTypes");
        if (roomTypes.isArray()) {
            int totalRoomTypeQuantity = 0;
            Set<String> roomTypeCodes = new HashSet<>();
            for (JsonNode roomType : roomTypes) {
                requireAny(roomType, "roomTypeCode", "code", "roomName", "name");

                String roomCode = firstText(roomType, "roomCode", "roomTypeCode", "code");
                if (roomCode.isBlank()) {
                    throw new BadRequestException("roomCode is required in roomsAndOutlets.roomTypes");
                }
                if (!ROOM_CODE_PATTERN.matcher(roomCode).matches()) {
                    throw new BadRequestException("roomCode must match ^[A-Z_]{2,20}$");
                }
                if (!roomTypeCodes.add(roomCode)) {
                    throw new BadRequestException("roomCode must be unique in roomsAndOutlets.roomTypes");
                }

                int quantity = firstInt(roomType, "quantity", "qty", "count");
                if (quantity <= 0) {
                    throw new BadRequestException("Room type quantity must be greater than zero");
                }
                totalRoomTypeQuantity += quantity;
                String roomTypeKey = resolveRoomTypeKey(roomType, "roomsAndOutlets.roomTypes[]");
                roomTypeLimits.put(roomTypeKey, quantity);

                int maximumGuestOccupancy = firstInt(roomType, "maximumGuestOccupancy", "maxOccupancy", "occupancy");
                if (maximumGuestOccupancy <= 0) {
                    throw new BadRequestException("Room type maximumGuestOccupancy must be greater than zero");
                }
            }

            if (totalRoomTypeQuantity > 0 && totalRoomTypeQuantity != totalRoomsFromPropertyDetails) {
                throw new BadRequestException("Sum of room type quantities must equal totalNoOfRooms");
            }
        }

        return new AllocationLimits(roomTypeLimits, propertyAreaLimits);
    }

    private void validatePropertyDetails(JsonNode propertyDetails) {
        requireAny(propertyDetails, "name", "propertyName");
        requireAny(propertyDetails, "propertyType", "type");
        require(propertyDetails, "propertyCode");
        requireAny(propertyDetails, "totalNoOfRooms", "totalRooms");
        requireAny(propertyDetails, "totalNoOfFloors", "totalFloors");
        requireAny(propertyDetails, "address", "addressLine1");
        require(propertyDetails, "city");
        require(propertyDetails, "state");
        require(propertyDetails, "country");
        requireAny(propertyDetails, "zipCode", "postalCode", "zipPostalCode");
        requireAny(propertyDetails, "contactName", "primaryContactName");
        requireAny(propertyDetails, "contactNumber", "phoneNumber", "phone");
        require(propertyDetails, "timeZone");
        require(propertyDetails, "nightAuditTime");
        require(propertyDetails, "checkInTime");
        require(propertyDetails, "checkOutTime");

        int totalRooms = firstInt(propertyDetails, "totalNoOfRooms", "totalRooms");
        if (totalRooms <= 0) {
            throw new BadRequestException("totalNoOfRooms must be greater than zero");
        }

        int totalFloors = firstInt(propertyDetails, "totalNoOfFloors", "totalFloors");
        if (totalFloors <= 0) {
            throw new BadRequestException("totalNoOfFloors must be greater than zero");
        }

        String address = firstText(propertyDetails, "address", "addressLine1");
        if (address.length() < 10) {
            throw new BadRequestException("Address must have at least 10 characters");
        }

        String website = firstText(propertyDetails, "website");
        if (!website.isBlank() && !website.contains(".")) {
            throw new BadRequestException("Invalid website value");
        }

        String checkIn = firstText(propertyDetails, "checkInTime");
        String checkOut = firstText(propertyDetails, "checkOutTime");
        parseTime(checkIn, "checkInTime");
        parseTime(checkOut, "checkOutTime");
        parseTime(firstText(propertyDetails, "nightAuditTime"), "nightAuditTime");
        if (checkIn.equals(checkOut)) {
            throw new BadRequestException("checkOutTime must differ from checkInTime");
        }
    }

    private void validateRoomConfiguration(JsonNode roomConfiguration, AllocationLimits limits) {
        JsonNode floors = roomConfiguration.path("floors");
        if (limits.roomTypeLimits().isEmpty()) {
            throw new BadRequestException("At least one room type is required");
        }
        if (!floors.isArray() || floors.isEmpty()) {
            throw new BadRequestException("At least one floor configuration is required");
        }

        // roomConfiguration.roomTypes is optional; authoritative configured room types come from roomsAndOutlets.roomTypes.
        Set<String> roomTypeNames = new HashSet<>(limits.roomTypeLimits().keySet());

        Set<String> roomNumbers = new HashSet<>();
        Map<String, Integer> assignedPerRoomType = new HashMap<>();
        Map<String, Integer> assignedPerPropertyArea = new HashMap<>();
        int floorIndex = 0;
        for (JsonNode floor : floors) {
            requireAny(floor, "floorName", "name", "label");

            JsonNode nestedRoomTypes = floor.path("roomTypes");
            if (nestedRoomTypes.isArray() && !nestedRoomTypes.isEmpty()) {

                int roomTypeIndex = 0;

                for (JsonNode floorRoomType : nestedRoomTypes) {
                    String pathPrefix =
                            "roomConfiguration.floors[" + floorIndex + "].roomTypes[" + roomTypeIndex + "]";

                    validateFloorRoomTypeAssignment(
                            floorRoomType,
                            pathPrefix,
                            roomTypeNames,
                            roomNumbers,
                            assignedPerRoomType,
                            limits.roomTypeLimits()
                    );

                    roomTypeIndex++;
                }

            }

            JsonNode propertyAreas = floor.path("propertyAreas");
            if (propertyAreas.isArray()) {
                int propertyAreaIndex = 0;
                for (JsonNode floorPropertyArea : propertyAreas) {
                    String propertyAreaName = resolvePropertyAreaKey(
                        floorPropertyArea,
                        "roomConfiguration.floors[" + floorIndex + "].propertyAreas[" + propertyAreaIndex + "]"
                    );
                    if (!limits.propertyAreaLimits().containsKey(propertyAreaName)) {
                        throw validationError(
                            "UNKNOWN_PROPERTY_AREA",
                            "roomConfiguration.floors[" + floorIndex + "].propertyAreas[" + propertyAreaIndex + "]",
                            "Floor mapped to unknown property area: " + propertyAreaName
                        );
                    }

                    int assignedAreaCount = firstInt(floorPropertyArea, "quantity", "qty", "count");
                    if (assignedAreaCount <= 0) {
                        throw validationError(
                            "MISSING_PROPERTY_AREA_ASSIGNMENT",
                            "roomConfiguration.floors[" + floorIndex + "].propertyAreas[" + propertyAreaIndex + "]",
                            "Each property area assignment must include positive quantity"
                        );
                    }

                    int totalAreaAssigned = assignedPerPropertyArea.getOrDefault(propertyAreaName, 0) + assignedAreaCount;
                    assignedPerPropertyArea.put(propertyAreaName, totalAreaAssigned);

                    int configuredAreaLimit = limits.propertyAreaLimits().get(propertyAreaName);
                    if (totalAreaAssigned > configuredAreaLimit) {
                        throw validationError(
                            "PROPERTY_AREA_QUANTITY_EXCEEDED",
                            "roomConfiguration.floors[" + floorIndex + "].propertyAreas[" + propertyAreaIndex + "]",
                            "Assigned property areas exceed configured quantity for area: " + propertyAreaName
                        );
                    }
                    propertyAreaIndex++;
                }
            }

            floorIndex++;
        }

        for (String configuredRoomType : roomTypeNames) {
            if (assignedPerRoomType.getOrDefault(configuredRoomType, 0) <= 0) {
                throw validationError(
                    "ROOM_TYPE_UNASSIGNED",
                    "roomConfiguration.roomTypes",
                    "At least one room must be assigned for room type: " + configuredRoomType
                );
            }
        }
    }

    private ValidationException validationError(String code, String fieldPath, String message) {
        return new ValidationException(code, fieldPath, message);
    }

    private void validateFloorRoomTypeAssignment(
        JsonNode floorRoomType,
        String fieldPath,
        Set<String> roomTypeNames,
        Set<String> roomNumbers,
        Map<String, Integer> assignedPerRoomType,
        Map<String, Integer> roomTypeLimits
    ) {
        String roomTypeName = resolveRoomTypeKey(floorRoomType, fieldPath);
        if (!roomTypeNames.contains(roomTypeName)) {
            throw validationError(
                "UNKNOWN_ROOM_TYPE",
                fieldPath,
                "Floor mapped to unknown room type: " + roomTypeName
            );
        }

        int assignedCount = resolveAssignedRoomCount(floorRoomType, fieldPath, roomNumbers);
        int totalAssigned = assignedPerRoomType.getOrDefault(roomTypeName, 0) + assignedCount;
        assignedPerRoomType.put(roomTypeName, totalAssigned);

        Integer configuredLimit = roomTypeLimits.get(roomTypeName);
        if (configuredLimit != null && totalAssigned > configuredLimit) {
            throw validationError(
                "ROOM_TYPE_QUANTITY_EXCEEDED",
                fieldPath,
                "Assigned rooms exceed configured quantity for room type: " + roomTypeName
            );
        }
    }

    private int resolveAssignedRoomCount(JsonNode floorRoomType, String fieldPath, Set<String> roomNumbers) {
        JsonNode explicitRooms = floorRoomType.path("roomNumbers");
        if (explicitRooms.isArray() && !explicitRooms.isEmpty()) {
            int assignedCount = 0;
            for (JsonNode roomNumberNode : explicitRooms) {
                String roomNumber = roomNumberNode.asText().trim();
                if (roomNumber.isBlank() || !roomNumbers.add(roomNumber)) {
                    throw validationError(
                        "DUPLICATE_OR_BLANK_ROOM_NUMBER",
                        fieldPath + ".roomNumbers",
                        "Duplicate or blank room number found"
                    );
                }
                assignedCount++;
            }
            return assignedCount;
        }

        int assignedCount = firstInt(floorRoomType, "roomCount", "quantity", "qty", "count");
        if (assignedCount <= 0) {
            throw validationError(
                "MISSING_ROOM_ASSIGNMENT",
                fieldPath,
                "Each floor allocation must include roomNumbers or positive roomCount"
            );
        }
        return assignedCount;
    }

    private String resolveRoomTypeKey(JsonNode node, String fieldPath) {
        String key = firstText(node, "roomTypeCode", "code", "roomTypeName", "name", "roomName");
        if (key.isBlank()) {
            throw validationError("MISSING_ROOM_TYPE_KEY", fieldPath, "Room type identifier is required");
        }
        return key;
    }

    private String resolvePropertyAreaKey(JsonNode node, String fieldPath) {
        String key = firstText(node, "propertyAreaCode", "areaName", "name", "code");
        if (key.isBlank()) {
            throw validationError("MISSING_PROPERTY_AREA_KEY", fieldPath, "Property area identifier is required");
        }
        return key;
    }

    private void validateFinance(JsonNode finance) {
        JsonNode chartOfAccounts = finance.path("chartOfAccounts");
        JsonNode revenueMappings = finance.path("revenueMappings");
        if (!chartOfAccounts.isArray() || chartOfAccounts.isEmpty()) {
            throw new BadRequestException("At least one chart of account entry is required");
        }
        if (!revenueMappings.isArray() || revenueMappings.isEmpty()) {
            throw new BadRequestException("At least one revenue mapping is required");
        }

        Set<String> accountCodes = new HashSet<>();
        for (JsonNode account : chartOfAccounts) {
            String accountCode = account.path("accountCode").asText().trim();
            if (accountCode.isBlank()) {
                throw new BadRequestException("accountCode is required in chartOfAccounts");
            }

            String accountName = account.path("accountName").asText().trim();
            if (accountName.isBlank()) {
                throw new BadRequestException("accountName is required in chartOfAccounts");
            }

            String accountType = account.path("accountType").asText().trim();
            if (accountType.isBlank()) {
                throw new BadRequestException("accountType is required in chartOfAccounts");
            }

            String ledgerType = account.path("ledgerType").asText().trim();
            if (ledgerType.isBlank()) {
                throw new BadRequestException("ledgerType is required in chartOfAccounts");
            }

            if (account.path("active").isMissingNode() || account.path("active").isNull()) {
                throw new BadRequestException("active is required in chartOfAccounts");
            }

            accountCodes.add(accountCode);
        }

        for (JsonNode mapping : revenueMappings) {
            String chargeType = mapping.path("chargeType").asText().trim();
            if (chargeType.isBlank()) {
                throw new BadRequestException("chargeType is required in revenueMappings");
            }

            String mapGlAccount = mapping.path("mapGlAccount").asText().trim();
            if (!mapGlAccount.isBlank() && !"UNASSIGNED".equalsIgnoreCase(mapGlAccount) && !accountCodes.contains(mapGlAccount)) {
                throw new BadRequestException("Revenue mapping refers to unknown accountCode: " + mapGlAccount);
            }

            String status = mapping.path("status").asText().trim();
            if (status.isBlank()) {
                throw new BadRequestException("status is required in revenueMappings");
            }
        }
    }

    private void validatePayments(JsonNode payments) {
        JsonNode methods = payments.path("methods");
        if (!methods.isArray() || methods.isEmpty()) {
            throw new BadRequestException("At least one payment method is required");
        }

        for (JsonNode method : methods) {
            require(method, "paymentMethod");
            require(method, "accountMapping");
            if (method.path("allowRefund").isMissingNode() || method.path("allowRefund").isNull()) {
                throw new BadRequestException("allowRefund is required in payments.methods");
            }
            if (method.path("active").isMissingNode() || method.path("active").isNull()) {
                throw new BadRequestException("active is required in payments.methods");
            }
        }
    }

    private void validateTaxes(JsonNode taxes) {
        JsonNode rules = taxes.path("rules");
        if (!rules.isArray() || rules.isEmpty()) {
            throw new BadRequestException("At least one tax rule is required");
        }
        for (JsonNode rule : rules) {
            require(rule, "taxName");
            require(rule, "type");
            require(rule, "applicableOn");
            require(rule, "inclExcl");
            require(rule, "effectiveDate");
            require(rule, "status");
            if (rule.path("active").isMissingNode() || rule.path("active").isNull()) {
                throw new BadRequestException("active is required in taxes.rules");
            }
            if (rule.path("rate").asDouble() <= 0) {
                throw new BadRequestException("Tax rate must be greater than zero");
            }
        }
    }

    private void require(JsonNode node, String field) {
        JsonNode value = node.path(field);
        if (value.isMissingNode() || value.isNull() || (value.isTextual() && value.asText().isBlank())) {
            throw new BadRequestException("Missing required field: " + field);
        }
    }

    private void requireAny(JsonNode node, String... fields) {
        for (String field : fields) {
            JsonNode value = node.path(field);
            if (!value.isMissingNode() && !value.isNull() && (!value.isTextual() || !value.asText().isBlank())) {
                return;
            }
        }
        throw new BadRequestException("Missing required field: one of " + String.join(", ", fields));
    }

    private String firstText(JsonNode node, String... fields) {
        for (String field : fields) {
            JsonNode value = node.path(field);
            if (!value.isMissingNode() && !value.isNull()) {
                String text = value.asText().trim();
                if (!text.isBlank()) {
                    return text;
                }
            }
        }
        return "";
    }

    private int firstInt(JsonNode node, String... fields) {
        for (String field : fields) {
            JsonNode value = node.path(field);
            if (!value.isMissingNode() && !value.isNull()) {
                if (value.isNumber()) {
                    return value.asInt();
                }
                String text = value.asText().trim();
                if (!text.isBlank()) {
                    try {
                        return Integer.parseInt(text);
                    } catch (NumberFormatException ignored) {
                        return -1;
                    }
                }
            }
        }
        return -1;
    }

    private JsonNode firstObjectNode(JsonNode parent, String... fields) {
        for (String field : fields) {
            JsonNode node = parent.path(field);
            if (node.isObject()) {
                return node;
            }
        }
        return parent.path("__missing__");
    }

    private void parseTime(String value, String fieldName) {
        try {
            LocalTime.parse(value);
            return;
        } catch (DateTimeParseException ex) {
            // Fallback for 12-hour values from UI widgets, e.g. 11:55 AM
            try {
                DateTimeFormatter twelveHour = DateTimeFormatter.ofPattern("h:mm a", Locale.ENGLISH);
                LocalTime.parse(value.toUpperCase(Locale.ENGLISH), twelveHour);
            } catch (DateTimeParseException innerEx) {
                throw new BadRequestException("Invalid time format for: " + fieldName);
            }
        }
    }

    private record AllocationLimits(Map<String, Integer> roomTypeLimits, Map<String, Integer> propertyAreaLimits) {
    }
}

package com.pms.property.publish.validator;

import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
import static org.junit.jupiter.api.Assertions.assertThrows;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.pms.property.common.exception.BadRequestException;
import org.junit.jupiter.api.Test;

class PublishValidatorTest {

    private final PublishValidator validator = new PublishValidator();
    private final ObjectMapper objectMapper = new ObjectMapper();

    @Test
    void shouldAcceptUiFinancePaymentTaxFields() throws Exception {
        assertDoesNotThrow(() -> validator.validate(objectMapper.readTree(validPayload())));
    }

    @Test
    void shouldRejectMissingAccountCode() {
        String payload = validPayload().replace("\"accountCode\": \"REV_ROOM\",\n", "");
        assertThrows(BadRequestException.class, () -> validator.validate(objectMapper.readTree(payload)));
    }

    @Test
    void shouldRejectUnknownMappedRevenueAccount() {
        String payload = validPayload().replace("\"mapGlAccount\": \"REV_ROOM\"", "\"mapGlAccount\": \"UNKNOWN\"");
        assertThrows(BadRequestException.class, () -> validator.validate(objectMapper.readTree(payload)));
    }

    @Test
    void shouldAcceptPendingRevenueMappingWithUnassignedAccount() throws Exception {
        String payload = validPayload()
            .replace("\"mapGlAccount\": \"REV_ROOM\"", "\"mapGlAccount\": \"UNASSIGNED\"")
            .replace("\"status\": \"MAPPED\"", "\"status\": \"PENDING\"");
        assertDoesNotThrow(() -> validator.validate(objectMapper.readTree(payload)));
    }

    @Test
    void shouldRejectMissingPaymentMethodRequiredFields() {
        String payload = validPayload().replace("\"allowRefund\": true,\n", "");
        assertThrows(BadRequestException.class, () -> validator.validate(objectMapper.readTree(payload)));
    }

    @Test
    void shouldRejectMissingTaxRate() {
        String payload = validPayload().replace("\"rate\": 18.0,\n", "");
        assertThrows(BadRequestException.class, () -> validator.validate(objectMapper.readTree(payload)));
    }

    @Test
    void shouldAcceptWithoutRoomConfigurationRoomTypes() throws Exception {
        String payload = validPayload().replace(
            """
                "roomTypes": [
                  {"name": "Standard Deluxe", "occupancy": 2}
                ],
            """,
            ""
        );
        assertDoesNotThrow(() -> validator.validate(objectMapper.readTree(payload)));
    }

    @Test
    void shouldAcceptFloorConfigurationAlias() throws Exception {
        String payload = validPayload().replace("\"roomConfiguration\"", "\"floorConfiguration\"");
        assertDoesNotThrow(() -> validator.validate(objectMapper.readTree(payload)));
    }

    private String validPayload() {
        return """
            {
              "propertyDetails": {
                "propertyName": "Seaside Retreat",
                "propertyType": "HOTEL",
                "propertyCode": "P-1001",
                "totalNoOfRooms": 2,
                "totalNoOfFloors": 1,
                "addressLine1": "123 Beach Road",
                "city": "Panaji",
                "state": "Goa",
                "country": "India",
                "zipCode": "403001",
                "timeZone": "Asia/Kolkata",
                "primaryContactName": "Nikhil",
                "phoneNumber": "+919999999999",
                "checkInTime": "11:55 AM",
                "checkOutTime": "00:00",
                "nightAuditTime": "11:55 PM"
              },
              "roomsAndOutlets": {
                "roomTypes": [
                  {"roomName": "Standard Deluxe", "quantity": 2, "maximumGuestOccupancy": 2}
                ]
              },
              "roomConfiguration": {
                "roomTypes": [
                  {"name": "Standard Deluxe", "occupancy": 2}
                ],
                "floors": [
                  {"floorName": "2", "roomTypeName": "Standard Deluxe", "roomNumbers": ["201", "202"]}
                ]
              },
              "finance": {
                "chartOfAccounts": [
                  {
                    "accountCode": "REV_ROOM",
                    "accountName": "Room Revenue",
                    "accountType": "REVENUE",
                    "ledgerType": "LIABILITY",
                    "active": true
                  }
                ],
                "revenueMappings": [
                  {
                    "chargeType": "Room Charges",
                    "mapGlAccount": "REV_ROOM",
                    "status": "MAPPED",
                    "description": "Room Booking Revenue"
                  }
                ]
              },
              "payments": {
                "methods": [
                  {
                    "paymentMethod": "CASH",
                    "accountMapping": "CASH_LEDGER",
                    "allowRefund": true,
                    "active": true
                  }
                ]
              },
              "taxes": {
                "rules": [
                  {
                    "taxName": "GST",
                    "type": "PERCENTAGE",
                    "rate": 18.0,
                    "applicableOn": "ADD_ON",
                    "inclExcl": "EXCLUSIVE",
                    "effectiveDate": "2026-06-01",
                    "active": true,
                    "status": "ACTIVE",
                    "priority": 1
                  }
                ]
              }
            }
            """;
    }
}

