create table property_area ( id bigint generated by default as identity primary key, property_id varchar(36) not null, area_name varchar(150) not null, quantity integer not null, maximum_capacity integer not null, description varchar(1000), amenities_csv varchar(2000), images_csv varchar(4000), constraint fk_property_area_property foreign key (property_id) references property(id) );
create table room_outlet_type ( id bigint generated by default as identity primary key, property_id varchar(36) not null, room_name varchar(150) not null, quantity integer not null, available_for_sell boolean not null, maximum_guest_occupancy integer not null, description varchar(1000), amenities_csv varchar(2000), images_csv varchar(4000), constraint fk_room_outlet_type_property foreign key (property_id) references property(id) );
create index idx_property_area_property on property_area(property_id); create index idx_room_outlet_type_property on room_outlet_type(property_id);

create table property_area ( id bigint generated by default as identity primary key, property_id varchar(36) not null, area_name varchar(150) not null, quantity integer not null, maximum_capacity integer not null, description varchar(1000), amenities_csv varchar(2000), images_csv varchar(4000), constraint fk_property_area_property foreign key (property_id) references property(id) );
create table room_outlet_type ( id bigint generated by default as identity primary key, property_id varchar(36) not null, room_name varchar(150) not null, room_code varchar(80), quantity integer not null, available_for_sell boolean not null, maximum_guest_occupancy integer not null, description varchar(1000), amenities_csv varchar(2000), images_csv varchar(4000), constraint fk_room_outlet_type_property foreign key (property_id) references property(id) );
create index idx_property_area_property on property_area(property_id); create index idx_room_outlet_type_property on room_outlet_type(property_id); create unique index uq_room_outlet_type_property_room_code on room_outlet_type(property_id, room_code) where room_code is not null;

package Policy_Management.Policy.controller;

import Policy_Management.Policy.dto.APIResponse;
import Policy_Management.Policy.dto.PolicyListResponse;
import Policy_Management.Policy.dto.PolicyDto;
import Policy_Management.Policy.dto.Status;
import Policy_Management.Policy.service.PolicyService;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.util.List;

@RestController
@RequestMapping("/api/v1/policies")
public class PolicyController {

    private static final Logger LOGGER = LoggerFactory.getLogger(PolicyController.class);
    private final PolicyService service;

    @Autowired
    public PolicyController(PolicyService service) {
        this.service = service;
    }

    @PostMapping(value = "/createPolicy")
    public ResponseEntity<APIResponse<PolicyDto>> create(@RequestBody PolicyDto dto) {
        LOGGER.info("POST /api/v1/policies/createPolicy request: {}", dto);
        PolicyDto created = service.createPolicy(dto);
        APIResponse<PolicyDto> response = new APIResponse<>("success", "Policy created successfully", created);
        LOGGER.info("POST /api/v1/policies/createPolicy response: {}", response);
        return new ResponseEntity<>(response, HttpStatus.CREATED);
    }

    @GetMapping (value = "/getAllPolicies")
